MINUS = '−'
NUMW = {1: 'one', 2: 'two', 3: 'three', 4: 'four', 5: 'five', 6: 'six', 7: 'seven', 8: 'eight', 9: 'nine', 10: 'ten'}

def neg(s):
    return str(s).replace('-', MINUS)

def _h(x):
    return x + math.copysign(1e-09, x)

def P(x, d=1):
    return neg(f'{_h(100 * x):.{d}f}')

def F(x, d=1):
    return neg(f'{_h(x):.{d}f}')

def S(x, d=1):
    return neg(f'{x:+.{d}f}')

def rng(lo, hi, d=1, scale=100):
    a, b = (scale * lo, scale * hi)
    return f'{F(a, d)} to {F(b, d)}' if a < 0 or b < 0 else f'{F(a, d)}–{F(b, d)}'

def cip(e, d=1):
    return f"{P(e['estimate'], d)}% (95% CI {P(e['lower'], d)}–{P(e['upper'], d)}%)"

def cis(e, d=1):
    return f"{P(e['estimate'], d)}%; 95% CI {P(e['lower'], d)}–{P(e['upper'], d)}%"

def cpi(e, d=1):
    return f"{F(100 * e['estimate'], d)} pp; 95% CI {rng(e['lower'], e['upper'], d)}"

def cin(e, d=1):
    return f"{P(e['lower'], d)}–{P(e['upper'], d)}%"

def nof(e):
    return f"{e['events']} of {e['n']}"

def psi(g, R='K2_base'):
    x = R3[R]['Psi'][g]
    return f"{F(x['pp'])} pp (95% CI {rng(x['ci_pp'][0], x['ci_pp'][1], 1, 1)})"

def wording(e):
    lo, hi = (100 * e['lower'], 100 * e['upper'])
    if lo >= -2 and hi <= 2:
        return 'similar'
    if lo > 0:
        return 'higher'
    if hi < 0:
        return 'lower'
    return 'inconclusive'
