def lgt(p):
    return math.log(p / (1 - p))

def expit(x):
    return 1 / (1 + math.exp(-x))
B35, B510 = (100 * expit((lgt(0.03) + lgt(0.05)) / 2), 100 * expit((lgt(0.05) + lgt(0.1)) / 2))

def zones_of(K3, lvl):
    z = {t: list(K3['by_threshold'][t]['instability_zones_risk_pct'][lvl]) for t in ['3.0', '5.0', '10.0']}
    z['3.0'][1] = min(z['3.0'][1], B35)
    z['5.0'][0] = max(z['5.0'][0], B35)
    z['5.0'][1] = min(z['5.0'][1], B510)
    z['10.0'][0] = max(z['10.0'][0], B510)
    return z

def zone_text(z):
    parts, cur = ([], list(z['3.0']))
    for t in ['5.0', '10.0']:
        if z[t][0] <= cur[1] + 1e-09:
            cur[1] = max(cur[1], z[t][1])
        else:
            parts.append(cur)
            cur = list(z[t])
    parts.append(cur)
    s = [f'{F(a)}–{F(b)}%' for a, b in parts]
    return s[0] if len(s) == 1 else ', '.join(s[:-1]) + ' and ' + s[-1]
