def fmt_cell(s, kind, weighted=False):
    if s is None or s.get('n', 0) == 0:
        return '—'
    if kind == 'pct':
        return f"{F(s['pct'])}" if weighted else f"{s['count']} ({F(s['pct'])})"
    if kind == 'median':
        return f"{F(s['median'], 2)} ({F(s['q1'], 2)}–{F(s['q3'], 2)})"
    return f"{F(s['mean'])} ({F(s['sd'])})"

def table1():
    rows = [['A. First-visit characteristics']]
