        urine = any((k in lab for k in ['Urine', 'UACR']))
        dp = 2 if 'creatinine' in lab and (not urine) or 'HbA1c' in lab else 1
        v = (lambda s: f"{F(s['median'], 1)} ({F(s['q1'], 1)}–{F(s['q3'], 1)})") if urine else lambda s: f"{F(s['mean'], dp)} ({F(s['sd'], dp)})"
        if 'Systolic' in lab:
            cvt = f"SDw {F(s7['sd_w'])} mm Hg"
